SET NAMES utf8mb4;
SET FOREIGN_KEY_CHECKS = 0;

CREATE DATABASE IF NOT EXISTS `quanlycv` DEFAULT CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
USE `quanlycv`;

-- ----------------------------
-- Table structure for users
-- ----------------------------
DROP TABLE IF EXISTS `users`;
CREATE TABLE `users` (
  `id` varchar(128) NOT NULL,
  `username` varchar(128) NOT NULL,
  `password` varchar(255) NOT NULL,
  `role` varchar(50) NOT NULL DEFAULT 'vanthu',
  `created_at` bigint(20) DEFAULT NULL,
  PRIMARY KEY (`username`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- Records of users
BEGIN;
COMMIT;

-- ----------------------------
-- Table structure for cong_van
-- ----------------------------
DROP TABLE IF EXISTS `cong_van`;
CREATE TABLE `cong_van` (
  `id` varchar(128) NOT NULL,
  `loai_cong_van` varchar(50) NOT NULL,
  `so_ky_hieu` varchar(255) DEFAULT NULL,
  `nguon_cong_van` varchar(255) DEFAULT NULL,
  `don_vi_ufm_co_so_chinh` varchar(255) DEFAULT NULL,
  `phong_ban` varchar(255) DEFAULT NULL,
  `co_quan_ban_hanh` varchar(255) DEFAULT NULL,
  `don_vi_chi_tiet` varchar(255) DEFAULT NULL,
  `loai_van_ban` varchar(255) DEFAULT NULL,
  `ngay_den` date DEFAULT NULL,
  `ngay_ban_hanh` date DEFAULT NULL,
  `trich_yeu` text DEFAULT NULL,
  `drive_link` text DEFAULT NULL,
  `response_doc_id` varchar(128) DEFAULT NULL,
  `lien_ket_cong_van_di_id` varchar(128) DEFAULT NULL,
  `created_at` bigint(20) DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `idx_loai_cong_van` (`loai_cong_van`),
  KEY `idx_so_ky_hieu` (`so_ky_hieu`),
  KEY `idx_ngay_ban_hanh` (`ngay_ban_hanh`),
  KEY `idx_ngay_den` (`ngay_den`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

